<?php
require __DIR__.'/app/bootstrap.php';$u=require_user();header('Content-Type: text/html; charset=utf-8');
$error='';$articles=[];
try{$termId=max(0,(int)($_GET['term_id']??0));$sql='SELECT a.id,a.title,a.status,a.updated_at,s.name site FROM articles a JOIN sites s ON s.id=a.site_id';if($termId){$sql.=' JOIN article_terms at ON at.article_id=a.id AND at.term_id=?';}$sql.=' ORDER BY a.updated_at DESC LIMIT 100';$q=db()->prepare($sql);$q->execute($termId?[$termId]:[]);$articles=$q->fetchAll();}catch(Throwable $e){$error='Az adatbázis nem érhető el.';error_log($e->getMessage());}
?><!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>comesy Editor · Cikkek</title><link rel="stylesheet" href="/assets/ui.css"><script src="/assets/ui.js" defer></script><style>body{font-family:system-ui;margin:0}.wrap{max-width:1100px;margin:auto;padding:24px}.head{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.btn{background:#315fd6;color:white;padding:12px 17px;border-radius:8px}.card{padding:24px;margin-top:20px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:13px;border-bottom:1px solid var(--line)}@media(max-width:600px){.wrap{padding:14px}th:nth-child(3),td:nth-child(3){display:none}}</style></head><body><?php require __DIR__.'/app/header.php'; ?><main class="wrap"><div class="head"><h1>Cikkek<?php if(!empty($termId)):?> · Besorolás #<?=(int)$termId?><?php endif;?></h1><a class="btn" href="/editor.php">+ Új cikk</a></div><?php if($error):?><p><?=h($error)?></p><?php endif;?><div class="comesy-filters"><label class="comesy-search"><span>Keresés</span><input type="search" data-list-search="article-list" placeholder="Cím vagy webhely keresése…" autocomplete="off"></label><label><span>Státusz</span><select data-list-filter="article-list" data-filter-field="status"><option value="">Összes státusz</option><option value="draft">Piszkozat</option><option value="review">Ellenőrzés</option><option value="scheduled">Időzített</option><option value="published">Publikált</option><option value="archived">Archivált</option></select></label></div><div class="card comesy-list-card"><table class="comesy-article-table"><thead><tr><th>Cím</th><th>Webhely</th><th>Státusz</th><th>Utolsó módosítás</th></tr></thead><tbody id="article-list"><?php foreach($articles as $a):?><tr data-status="<?=h($a['status'])?>"><td><a href="/editor.php?id=<?=(int)$a['id']?>"><?=h($a['title'])?></a></td><td><?=h($a['site'])?></td><td><?=h(['draft'=>'Piszkozat','review'=>'Ellenőrzés','scheduled'=>'Időzített','published'=>'Publikált','archived'=>'Archivált'][$a['status']]??$a['status'])?></td><td><?=h($a['updated_at'])?></td></tr><?php endforeach;?></tbody></table><p class="comesy-empty-filter" data-empty-for="article-list" hidden>Nincs a szűrésnek megfelelő cikk.</p><?php if(!$articles):?><p>Még nincs mentett cikk.</p><?php endif;?></div></main></body></html>
